using CsvHelper;
using CsvHelper.Configuration;
using Financeiro.Application;
using Financeiro.Domain;
using Financeiro.Infrastructure;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.EntityFrameworkCore;
using System.Globalization;
using System.Text;

namespace Financeiro.Api.Controllers;

[ApiController,Authorize,Route("api/v1/debts")]
public sealed class DebtsController(FinanceiroDbContext db,ICurrentUser current):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(CancellationToken ct)=>Ok(await db.Debts.AsNoTracking().Include(x=>x.Installments).Select(x=>new{x.Id,x.Name,x.Type,x.Principal,x.InterestRate,x.InstallmentCount,x.StartDate,Paid=x.Installments.Where(i=>i.PaidAt!=null).Sum(i=>i.Amount),Remaining=x.Installments.Where(i=>i.PaidAt==null).Sum(i=>i.Amount),PaidInstallments=x.Installments.Count(i=>i.PaidAt!=null),RemainingInstallments=x.Installments.Count(i=>i.PaidAt==null),NextDue=x.Installments.Where(i=>i.PaidAt==null).OrderBy(i=>i.DueDate).Select(i=>(DateOnly?)i.DueDate).FirstOrDefault()}).ToListAsync(ct));
 [HttpPost]public async Task<IActionResult>Create(DebtRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Name)||r.Name.Trim().Length>160||r.Principal<=0||r.InterestRate<0||r.InstallmentCount<1||r.InstallmentCount>600)return BadRequest("Dívida inválida.");var d=new Debt{UserId=current.UserId,Name=r.Name.Trim(),Type=r.Type,Principal=r.Principal,InterestRate=r.InterestRate,InstallmentCount=r.InstallmentCount,StartDate=r.StartDate};var amount=decimal.Round(r.Principal/r.InstallmentCount,2);for(var i=1;i<=r.InstallmentCount;i++)d.Installments.Add(new DebtInstallment{UserId=current.UserId,Number=i,Amount=i==r.InstallmentCount?r.Principal-amount*(r.InstallmentCount-1):amount,DueDate=r.StartDate.AddMonths(i)});db.Add(d);await db.SaveChangesAsync(ct);return Ok(d);}
 [HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,DebtRequest r,CancellationToken ct){var d=await db.Debts.Include(x=>x.Installments).SingleOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();if(string.IsNullOrWhiteSpace(r.Name)||r.Name.Trim().Length>160||r.Principal<=0||r.InterestRate<0||r.InstallmentCount<1||r.InstallmentCount>600)return BadRequest("Dívida inválida.");if(d.Installments.Any(x=>x.PaidAt is not null))return Conflict("Não é possível alterar uma dívida com parcelas pagas.");d.Name=r.Name.Trim();d.Type=r.Type;d.Principal=r.Principal;d.InterestRate=r.InterestRate;d.InstallmentCount=r.InstallmentCount;d.StartDate=r.StartDate;db.DebtInstallments.RemoveRange(d.Installments);var amount=decimal.Round(r.Principal/r.InstallmentCount,2);for(var i=1;i<=r.InstallmentCount;i++)d.Installments.Add(new DebtInstallment{UserId=current.UserId,Number=i,Amount=i==r.InstallmentCount?r.Principal-amount*(r.InstallmentCount-1):amount,DueDate=r.StartDate.AddMonths(i)});await db.SaveChangesAsync(ct);return Ok(d);}
 [HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){var d=await db.Debts.FindAsync([id],ct);if(d is null)return NotFound();db.Remove(d);await db.SaveChangesAsync(ct);return NoContent();}
}

[ApiController,Authorize,Route("api/v1/subscriptions")]
public sealed class SubscriptionsController(FinanceiroDbContext db,ICurrentUser current):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(CancellationToken ct)=>Ok(await db.Subscriptions.AsNoTracking().Select(x=>new{x.Id,x.Name,x.Amount,x.Cycle,x.BillingDay,x.StartDate,x.AccountId,x.CategoryId,x.IsActive,NextBillingDate=x.StartDate}).ToListAsync(ct));
 [HttpPost]public async Task<IActionResult>Create(SubscriptionRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Name)||r.Name.Trim().Length>160||r.Amount<=0||r.BillingDay is<1 or>31)return BadRequest("Assinatura inválida.");if(!await RelatedIdsBelongToUser(r.AccountId,r.CategoryId,ct))return BadRequest("Conta ou categoria inválida.");var x=new Subscription{UserId=current.UserId,Name=r.Name.Trim(),Amount=r.Amount,Cycle=r.Cycle,BillingDay=r.BillingDay,StartDate=r.StartDate,AccountId=r.AccountId,CategoryId=r.CategoryId,IsActive=r.IsActive};db.Add(x);await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,SubscriptionRequest r,CancellationToken ct){var x=await db.Subscriptions.FindAsync([id],ct);if(x is null)return NotFound();if(string.IsNullOrWhiteSpace(r.Name)||r.Name.Trim().Length>160||r.Amount<=0||r.BillingDay is<1 or>31||!await RelatedIdsBelongToUser(r.AccountId,r.CategoryId,ct))return BadRequest("Assinatura inválida.");x.Name=r.Name.Trim();x.Amount=r.Amount;x.Cycle=r.Cycle;x.BillingDay=r.BillingDay;x.StartDate=r.StartDate;x.AccountId=r.AccountId;x.CategoryId=r.CategoryId;x.IsActive=r.IsActive;await db.SaveChangesAsync(ct);return Ok(x);}
 private async Task<bool> RelatedIdsBelongToUser(Guid? accountId,Guid? categoryId,CancellationToken ct){return (accountId is null||await db.Accounts.AnyAsync(x=>x.Id==accountId,ct))&&(categoryId is null||await db.Categories.AnyAsync(x=>x.Id==categoryId&&x.Type==TransactionType.Expense,ct));}
 [HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){var x=await db.Subscriptions.FindAsync([id],ct);if(x is null)return NotFound();db.Remove(x);await db.SaveChangesAsync(ct);return NoContent();}
}

[ApiController,Authorize,Route("api/v1/credit-cards")]
public sealed class CreditCardsController(FinanceiroDbContext db,ICurrentUser current):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(CancellationToken ct)=>Ok(await db.CreditCards.AsNoTracking().Include(x=>x.Invoices).ThenInclude(i=>i.Installments).Select(x=>new{x.Id,x.Name,x.Bank,x.Brand,x.Limit,x.BestPurchaseDay,x.ClosingDay,x.DueDay,x.IsActive,Used=x.Invoices.SelectMany(i=>i.Installments).Where(i=>i.Invoice!.Status!=InvoiceStatus.Paid).Sum(i=>i.Amount),Available=x.Limit-x.Invoices.SelectMany(i=>i.Installments).Where(i=>i.Invoice!.Status!=InvoiceStatus.Paid).Sum(i=>i.Amount)}).ToListAsync(ct));
 [HttpPost]public async Task<IActionResult>Create(CreditCardRequest r,CancellationToken ct){if(Validate(r) is{}error)return BadRequest(error);var x=new CreditCard{UserId=current.UserId,Name=r.Name.Trim(),Bank=r.Bank.Trim(),Brand=r.Brand,Limit=r.Limit,BestPurchaseDay=r.BestPurchaseDay,ClosingDay=r.ClosingDay,DueDay=r.DueDay,IsActive=r.IsActive};db.Add(x);await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,CreditCardRequest r,CancellationToken ct){var x=await db.CreditCards.FindAsync([id],ct);if(x is null)return NotFound();if(Validate(r) is{}error)return BadRequest(error);x.Name=r.Name.Trim();x.Bank=r.Bank.Trim();x.Brand=r.Brand;x.Limit=r.Limit;x.BestPurchaseDay=r.BestPurchaseDay;x.ClosingDay=r.ClosingDay;x.DueDay=r.DueDay;x.IsActive=r.IsActive;await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){var x=await db.CreditCards.Include(c=>c.Invoices).SingleOrDefaultAsync(c=>c.Id==id,ct);if(x is null)return NotFound();if(x.Invoices.Count>0){x.IsActive=false;await db.SaveChangesAsync(ct);return NoContent();}db.Remove(x);await db.SaveChangesAsync(ct);return NoContent();}
 private static string? Validate(CreditCardRequest r)=>string.IsNullOrWhiteSpace(r.Name)||r.Name.Trim().Length>120?"Nome do cartão inválido.":string.IsNullOrWhiteSpace(r.Bank)||r.Bank.Trim().Length>120?"Instituição inválida.":r.Limit<0||r.BestPurchaseDay is<1 or>31||r.ClosingDay is<1 or>31||r.DueDay is<1 or>31?"Cartão inválido.":null;
 [HttpPost("{id:guid}/purchases")]public async Task<IActionResult>Purchase(Guid id,CardPurchaseRequest r,CancellationToken ct){if(r.TotalAmount<=0||r.InstallmentCount<1)return BadRequest("Compra inválida.");var card=await db.CreditCards.SingleOrDefaultAsync(x=>x.Id==id,ct);if(card is null)return NotFound();if(r.CategoryId is not null&&!await db.Categories.AnyAsync(x=>x.Id==r.CategoryId&&x.Type==TransactionType.Expense,ct))return BadRequest("Categoria inválida.");var purchase=new CreditCardPurchase{UserId=current.UserId,CreditCardId=id,Description=r.Description,TotalAmount=r.TotalAmount,PurchaseDate=r.PurchaseDate,CategoryId=r.CategoryId,InstallmentCount=r.InstallmentCount};for(var i=1;i<=r.InstallmentCount;i++){var date=r.PurchaseDate.AddMonths(i-1);var inv=await db.CreditCardInvoices.SingleOrDefaultAsync(x=>x.CreditCardId==id&&x.Month==date.Month&&x.Year==date.Year,ct);if(inv is null){var closing=new DateOnly(date.Year,date.Month,Math.Min(card.ClosingDay,DateTime.DaysInMonth(date.Year,date.Month)));inv=new CreditCardInvoice{UserId=current.UserId,CreditCardId=id,Month=date.Month,Year=date.Year,ClosingDate=closing,DueDate=closing.AddMonths(1).AddDays(card.DueDay-1),Status=InvoiceStatus.Open};db.Add(inv);await db.SaveChangesAsync(ct);}purchase.Installments.Add(new Installment{UserId=current.UserId,CreditCardPurchaseId=purchase.Id,CreditCardInvoiceId=inv.Id,Number=i,Total=r.InstallmentCount,Amount=i==r.InstallmentCount?r.TotalAmount-decimal.Round(r.TotalAmount/r.InstallmentCount,2)*(r.InstallmentCount-1):decimal.Round(r.TotalAmount/r.InstallmentCount,2)});}db.Add(purchase);await db.SaveChangesAsync(ct);return Ok(new { purchase.Id, purchase.CreditCardId, purchase.Description, purchase.TotalAmount, purchase.PurchaseDate, purchase.CategoryId, purchase.InstallmentCount, Installments = purchase.Installments.Select(x => new { x.Id, x.CreditCardInvoiceId, x.Number, x.Total, x.Amount }) });}
 [HttpGet("{id:guid}/invoices")]public async Task<IActionResult>Invoices(Guid id,CancellationToken ct){if(!await db.CreditCards.AnyAsync(x=>x.Id==id,ct))return NotFound();return Ok(await db.CreditCardInvoices.AsNoTracking().Where(x=>x.CreditCardId==id).Include(x=>x.Installments).OrderByDescending(x=>x.Year).ThenByDescending(x=>x.Month).ToListAsync(ct));}
 [HttpPost("invoices/{invoiceId:guid}/pay")]public async Task<IActionResult>PayInvoice(Guid invoiceId,InvoicePaymentRequest r,CancellationToken ct){var inv=await db.CreditCardInvoices.Include(x=>x.Installments).SingleOrDefaultAsync(x=>x.Id==invoiceId,ct);if(inv is null)return NotFound();if(inv.Status==InvoiceStatus.Paid)return Conflict("Fatura já paga.");if(!await db.Accounts.AnyAsync(x=>x.Id==r.AccountId,ct))return BadRequest("Conta inválida.");var amount=inv.Installments.Sum(x=>x.Amount);var payment=new Transaction{UserId=current.UserId,AccountId=r.AccountId,Description=$"Pagamento fatura {inv.Month:D2}/{inv.Year}",Amount=amount,Type=TransactionType.Expense,Status=TransactionStatus.Paid,Date=r.PaymentDate,PaidAt=r.PaymentDate};db.Transactions.Add(payment);inv.PaymentTransactionId=payment.Id;inv.Status=InvoiceStatus.Paid;inv.PaidAt=r.PaymentDate;await db.SaveChangesAsync(ct);return Ok(inv);}
}

[ApiController,Authorize,EnableRateLimiting("expensive"),Route("api/v1/reports")]
public sealed class ReportsController(FinanceiroDbContext db):ControllerBase
{
 [HttpGet("summary")]public async Task<IActionResult>Summary(DateOnly? from,DateOnly? to,CancellationToken ct){var start=from??DateOnly.FromDateTime(DateTime.UtcNow.AddMonths(-11));var end=to??DateOnly.FromDateTime(DateTime.UtcNow);var tx=await db.Transactions.AsNoTracking().Where(x=>x.Date>=start&&x.Date<=end&&x.Status!=TransactionStatus.Cancelled).ToListAsync(ct);return Ok(new{from=start,to=end,monthly=tx.GroupBy(x=>new{x.Date.Year,x.Date.Month}).OrderBy(g=>g.Key.Year).ThenBy(g=>g.Key.Month).Select(g=>new{month=$"{g.Key.Month:D2}/{g.Key.Year}",income=g.Where(x=>x.Type==TransactionType.Income).Sum(x=>x.Amount),expense=g.Where(x=>x.Type==TransactionType.Expense).Sum(x=>x.Amount)}),categories=tx.Where(x=>x.Type==TransactionType.Expense).GroupBy(x=>x.Category?.Name??"Outros").Select(g=>new{category=g.Key,value=g.Sum(x=>x.Amount)}),cards=await db.CreditCardInvoices.Where(x=>x.DueDate>=start&&x.DueDate<=end).GroupBy(x=>x.CreditCard!.Name).Select(g=>new{card=g.Key,value=g.SelectMany(x=>x.Installments).Sum(i=>i.Amount)}).ToListAsync(ct)});}
}

[ApiController,Authorize,EnableRateLimiting("search"),Route("api/v1/search")]
public sealed class SearchController(FinanceiroDbContext db):ControllerBase
{
 [HttpGet]public async Task<IActionResult>Search(string q,int limit=10,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(q))return Ok(Array.Empty<object>());q=q.Trim().ToLower();limit=Math.Clamp(limit,1,50);var tx=await db.Transactions.Where(x=>x.Description.ToLower().Contains(q)).Take(limit).Select(x=>new{type="transaction",x.Id,title=x.Description,value=x.Amount}).ToListAsync(ct);var ac=await db.Accounts.Where(x=>x.Name.ToLower().Contains(q)).Take(limit).Select(x=>new{type="account",x.Id,title=x.Name,value=(decimal?)null}).ToListAsync(ct);return Ok(tx.Cast<object>().Concat(ac).Take(limit));}
}

[ApiController,Authorize,Route("api/v1/notifications")]
public sealed class NotificationsController(FinanceiroDbContext db):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(bool unreadOnly=false,CancellationToken ct=default)=>Ok(await db.Notifications.AsNoTracking().Where(x=>!unreadOnly||!x.IsRead).OrderByDescending(x=>x.CreatedAt).Take(100).ToListAsync(ct));
 [HttpPost("{id:guid}/read")]public async Task<IActionResult>Read(Guid id,CancellationToken ct){var x=await db.Notifications.FindAsync([id],ct);if(x is null)return NotFound();x.IsRead=true;x.ReadAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);return NoContent();}
}

[ApiController,Authorize,EnableRateLimiting("csv"),Route("api/v1/import-export")]
public sealed class ImportExportController(FinanceiroDbContext db):ControllerBase
{
 [HttpGet("transactions.csv")]public async Task<IActionResult>Export(DateOnly? from,DateOnly? to,CancellationToken ct){var q=db.Transactions.AsNoTracking().AsQueryable();if(from is not null)q=q.Where(x=>x.Date>=from);if(to is not null)q=q.Where(x=>x.Date<=to);var rows=await q.Select(x=>new{description=x.Description,amount=x.Amount,type=x.Type.ToString(),status=x.Status.ToString(),date=x.Date.ToString("dd/MM/yyyy"),notes=x.Notes}).ToListAsync(ct);await using var stream=new MemoryStream();await using(var writer=new StreamWriter(stream,Encoding.UTF8,leaveOpen:true)){await using var csv=new CsvWriter(writer,CultureInfo.GetCultureInfo("pt-BR"));csv.WriteField("description");csv.WriteField("amount");csv.WriteField("type");csv.WriteField("status");csv.WriteField("date");csv.WriteField("notes");await csv.NextRecordAsync();foreach(var row in rows){csv.WriteField(NeutralizeSpreadsheetFormula(row.description));csv.WriteField(row.amount);csv.WriteField(row.type);csv.WriteField(row.status);csv.WriteField(row.date);csv.WriteField(NeutralizeSpreadsheetFormula(row.notes));await csv.NextRecordAsync();}}return File(stream.ToArray(),"text/csv","transacoes.csv");}
 private static string? NeutralizeSpreadsheetFormula(string? value)=>string.IsNullOrEmpty(value)||value[0] is not ('=' or '+' or '-' or '@')?value:"'"+value;
 [HttpPost("transactions/preview")]public async Task<IActionResult>Preview(IFormFile file,CancellationToken ct){const long maxBytes=5*1024*1024;const int maxRecords=100;const int maxFieldLength=4096;if(file is null||file.Length==0)return BadRequest("Arquivo vazio.");if(file.Length>maxBytes)return BadRequest("Arquivo excede 5 MB.");if(!string.IsNullOrWhiteSpace(file.ContentType)&&file.ContentType is not "text/csv" and not "application/csv" and not "application/vnd.ms-excel")return BadRequest("Formato de arquivo inválido.");using var reader=new StreamReader(file.OpenReadStream(),Encoding.UTF8,detectEncodingFromByteOrderMarks:true,bufferSize:8192,leaveOpen:false);var csvConfig=new CsvConfiguration(CultureInfo.GetCultureInfo("pt-BR")){BadDataFound=context=>throw new BadHttpRequestException("CSV malformado.")};using var csv=new CsvReader(reader,csvConfig);var records=new List<Dictionary<string,string?>>(maxRecords);try{await foreach(var row in csv.GetRecordsAsync<dynamic>(ct)){var values=((IDictionary<string,object>)row).ToDictionary(x=>x.Key,x=>x.Value?.ToString());if(values.Count>50||values.Any(x=>x.Value?.Length>maxFieldLength))return BadRequest("Campo CSV excede o limite permitido.");records.Add(values);if(records.Count>=maxRecords)break;}}catch(FormatException){return BadRequest("CSV malformado.");}return Ok(new{rows=records,totalPreview=records.Count});}
}
